class Solution {
public:
    int minimumAverageDifference(vector<int>& nums) {
        int n = nums.size();
        long long total = 0;
        for (int x : nums) total += x;
        long long pref = 0;
        long long minDiff = LLONG_MAX;
        int bestIdx = 0;
        for (int i = 0; i < n; i++) {
            pref += nums[i];
            long long leftAvg = pref / (i + 1);
            int rightCnt = n - 1 - i;
            long long rightAvg = rightCnt > 0 ? (total - pref) / rightCnt : 0;
            long long diff = abs(leftAvg - rightAvg);
            if (diff < minDiff) {
                minDiff = diff;
                bestIdx = i;
            }
        }
        return bestIdx;
    }
};

