        long minDiff = Long.MAX_VALUE;
        int bestIdx = 0;
        for (int i = 0; i < n; i++) {
            pref += nums[i];
            long leftAvg = pref / (i + 1);
            int rightCnt = n - 1 - i;
            long rightAvg = rightCnt > 0 ? (total - pref) / rightCnt : 0;
            long diff = Math.abs(leftAvg - rightAvg);
            if (diff < minDiff) {
                minDiff = diff;
                bestIdx = i;
